// Cleans raw form input into a predictable shape before anything downstream
// depends on it. Form labels are read tolerantly so renaming a field in the
// trigger does not silently produce empty values.

const form = $input.first().json;

const pick = (...labels) => {
  for (const label of labels) {
    if (form[label] !== undefined && String(form[label]).trim() !== '') {
      return String(form[label]).trim();
    }
  }
  return '';
};

const email = pick('Work Email', 'Email', 'email').toLowerCase();
const emailValid = /^[^@\s]+@[^@\s.]+\.[^@\s]+$/.test(email);
const domain = emailValid ? email.split('@')[1] : '';

const freeProviders = [
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com',
  'mail.com', 'yandex.com', 'msn.com',
];
const isFreeEmail = freeProviders.includes(domain);

const firstName = pick('First Name');
const lastName = pick('Last Name');

// Back fill company from the email domain when the form left it blank.
let company = pick('Company');
if (!company && domain && !isFreeEmail) {
  company = domain
    .split('.')[0]
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

let website = pick('Website');
if (!website && domain && !isFreeEmail) website = domain;
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
website = website.replace(/\/+$/, '');

return [{
  json: {
    email,
    email_valid: emailValid,
    domain,
    is_free_email: isFreeEmail,
    first_name: firstName,
    last_name: lastName,
    full_name: [firstName, lastName].filter(Boolean).join(' '),
    phone: pick('Phone Number', 'Phone'),
    company,
    website,
    need: pick('What do you need help with?'),
    budget: pick('Budget'),
    submitted_at: $now.toISO(),
  },
}];

