// Reads the model output without assuming a provider specific shape, then
// makes the routing decision in one place so the branches downstream only
// have to read a boolean.

const lead = $('Normalize Lead Data').first().json;
const config = $('Set Lead Data Fields').first().json;
const threshold = Number(config.hot_score_threshold) || 7;
const raw = $input.first().json;

function extractPayload(input) {
  if (typeof input === 'string') return input;
  const parts = (container) =>
    container && Array.isArray(container.parts)
      ? container.parts.map((p) => p.text).join('')
      : null;
  const candidates = [
    input.output,
    input.text,
    input.response,
    input.message && input.message.content,
    parts(input.content),
    input.candidates && input.candidates[0] ? parts(input.candidates[0].content) : null,
    input.content,
  ];
  for (const value of candidates) {
    if (value && typeof value === 'object') return value;
    if (typeof value === 'string' && value.trim()) return value;
  }
  return JSON.stringify(input);
}

function parseVerdict(input) {
  const payload = extractPayload(input);
  if (payload && typeof payload === 'object') return payload;
  const cleaned = String(payload).replace(/```json/gi, '').replace(/```/g, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) return null;
  try {
    const parsed = JSON.parse(cleaned.slice(start, end + 1));
    return parsed && parsed.score !== undefined ? parsed : null;
  } catch (error) {
    return null;
  }
}

const parsed = parseVerdict(raw);

// An unreadable response must not silently bury a real lead, so it lands just
// under the threshold with an explicit note asking for a human look.
const verdict = parsed || {
  score: Math.max(0, threshold - 1),
  segment: 'unqualified',
  reason: 'The scoring model returned an unreadable response. Review this lead manually.',
  suggested_opener: '',
  disqualified: false,
};

const clamp = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.min(10, Math.max(0, Math.round(n)));
};

const score = clamp(verdict.score);
const disqualified = verdict.disqualified === true;

return [{
  json: {
    ...lead,
    score,
    segment: String(verdict.segment || 'unqualified'),
    reason: String(verdict.reason || ''),
    suggested_opener: String(verdict.suggested_opener || ''),
    disqualified,
    is_hot: score >= threshold && !disqualified && lead.email_valid,
    threshold,
  },
}];
